    source: { section: "§ 16", printedPage: 55, pdfPage: 60, book: { title: "Физика, 7 класс, 2022", authors: "Л. А. Исаченкова, Е. В. Громыко, Ю. Д. Лещинский", url: "https://e-padruchnik.adu.by/books/fizika/Fizika_Isachenkova_7kl_rus_2022.pdf" } },
    practice: { href: "/practice/family/uniform-motion-basic", label: "Потренировать путь, скорость и время" },
